@model Umbraco.Bench.Umbraco.Models.Blocks.PostListingModel

<section class="mx-auto max-w-6xl px-6 py-14 lg:px-8 lg:py-20">
    <div class="mb-9 flex items-end justify-between gap-6 border-b border-white/10 pb-5">
        <div>
            <p class="text-xs font-semibold tracking-[0.25em] text-cyan-300 uppercase">Latest writing</p>
            <h2 class="mt-3 text-3xl font-semibold tracking-tight text-white">Why MCP is awesome</h2>
        </div>
        <span class="text-sm text-stone-500">@Model.Posts.Count field notes</span>
    </div>
    <div class="grid gap-8 md:grid-cols-2">
        @foreach (var post in Model.Posts)
        {
            <article class="group overflow-hidden rounded-3xl border border-white/10 bg-white/[0.04] transition hover:-translate-y-1 hover:border-cyan-300/40">
                <a class="block" href="@post.Url">
                    <img class="aspect-[3/2] w-full object-cover" src="@post.ImageUrl" alt="@post.ImageAlt" />
                    <div class="p-7">
                        <time class="text-xs font-medium tracking-wider text-cyan-300 uppercase" datetime="@post.PublishedDate.ToString("yyyy-MM-dd")">@post.PublishedDate.ToString("MMMM d, yyyy")</time>
                        <h3 class="mt-3 text-2xl font-semibold tracking-tight text-white group-hover:text-cyan-100">@post.Heading</h3>
                        <p class="mt-4 leading-7 text-stone-400">@post.Summary</p>
                        <span class="mt-6 inline-flex text-sm font-semibold text-white">Read the field note →</span>
                    </div>
                </a>
            </article>
        }
    </div>
</section>
